import { NextResponse } from "next/server";
import { randomUUID } from "node:crypto";
import { db } from "@/lib/db";
import { checkRateLimit } from "@/lib/rate-limit";
import { trustedClientIp } from "@/app/api/_lib/client-ip";

export const runtime = "nodejs";

/**
 * Page-view capture endpoint. Called fire-and-forget by <VisitTracker/> mounted
 * in the marketing layout and the portal Shell. It records a single `Visit` row
 * and MUST NOT throw or block the caller — analytics is strictly best-effort.
 *
 * The client IP is the PROXY-ATTESTED address (`trustedClientIp`); we never
 * trust a body-supplied IP, nor the first hop of `X-Forwarded-For` — nginx
 * appends to that header, so its first entry is caller-chosen. That mattered
 * twice here: it was the rate-limit key (so one header defeated the 60/min cap
 * on durable row insertion), and it is PERSISTED to `Visit.ip`, which is what
 * the admin visitors/analytics pages attribute traffic and abuse to. A forged
 * value poisoned both.
 *
 * Bots are dropped by a coarse UA check. The visit "kind" (marketing vs portal)
 * comes from a `?k=` query param the mounter sets.
 *
 * Two shapes of POST arrive here:
 *  - a PAGEVIEW (has `path`): inserts the Visit row, attaches session/pvid/utm and
 *    a stable, consent-gated `visitorId` (see below).
 *  - a CLOSE beacon (`{ close, pvid, dur }`, often via navigator.sendBeacon on
 *    pagehide): stamps the dwell time onto the earlier row with that pvid. This is
 *    what makes "avg time on site" and bounce rate possible.
 *
 * Stable visitor id (recurring vs new): we keep a first-party `nx_vid` cookie and
 * persist it on each Visit, so a returning person is recognisable across sessions
 * without any third party. It is CONSENT-GATED to the site's own opt-out model
 * (lib/consent.ts): only minted/persisted unless the visitor explicitly chose
 * "necessary" (nxeon_cookie_consent=necessary), in which case visitorId stays null
 * and that person is only ever counted by the coarse IP path.
 */

const BOT_RE =
  /bot|crawl|spider|slurp|bingpreview|mediapartners|adsbot|facebookexternalhit|embedly|quora|pinterest|redditbot|whatsapp|telegrambot|discordbot|slackbot|semrush|ahrefs|mj12|dotbot|petalbot|yandex|baidu|duckduckbot|headless|phantomjs|python-requests|python-urllib|go-http|libwww|curl\/|wget\/|okhttp|axios\/|node-fetch|lighthouse|pagespeed|gtmetrix|pingdom|uptimerobot|statuscake|monitor|preview|scrapy/i;

const VID_COOKIE = "nx_vid";
const VID_MAX_AGE = 60 * 60 * 24 * 365; // 1 year
const CONSENT_COOKIE = "nxeon_cookie_consent";

/** Read one cookie value out of the raw Cookie header. */
function readCookie(req: Request, name: string): string | null {
  const raw = req.headers.get("cookie");
  if (!raw) return null;
  for (const part of raw.split("; ")) {
    if (part.startsWith(`${name}=`)) return part.slice(name.length + 1);
  }
  return null;
}

/** Clamp a client-supplied opaque id to something sane before it hits the DB. */
function cleanId(v: unknown): string | null {
  if (typeof v !== "string") return null;
  const s = v.trim();
  if (!s || s.length > 64 || !/^[A-Za-z0-9._-]+$/.test(s)) return null;
  return s;
}

function cleanUtm(v: unknown): string | null {
  if (typeof v !== "string") return null;
  const s = v.trim().slice(0, 120);
  return s || null;
}

export async function POST(req: Request) {
  try {
    // Unauthenticated endpoint that writes a durable row per hit — throttle
    // per-IP to cap unbounded row insertion. Over the limit: silent no-op.
    const ip = trustedClientIp(req);
    const rl = checkRateLimit(`track:${ip}`, { max: 120, windowMs: 60_000 });
    if (!rl.ok) {
      return new NextResponse(null, { status: 204 });
    }

    const url = new URL(req.url);
    const kindParam = url.searchParams.get("k");
    const kind = kindParam === "portal" ? "portal" : "marketing";

    const body = (await req.json().catch(() => ({}))) as {
      path?: unknown;
      referrer?: unknown;
      sessionId?: unknown;
      pvid?: unknown;
      isEntry?: unknown;
      utmSource?: unknown;
      utmMedium?: unknown;
      utmCampaign?: unknown;
      close?: unknown;
      dur?: unknown;
    };

    // --- CLOSE beacon: attach dwell time to the earlier pageview row ---
    if (body.close === true) {
      const pvid = cleanId(body.pvid);
      const durRaw = typeof body.dur === "number" ? body.dur : Number(body.dur);
      if (pvid && Number.isFinite(durRaw)) {
        // Cap at 30 min so a backgrounded tab can't record an absurd dwell.
        const durationMs = Math.min(Math.max(Math.round(durRaw), 0), 30 * 60_000);
        await db.visit.updateMany({ where: { pvid }, data: { durationMs } });
      }
      return NextResponse.json({ ok: true });
    }

    const ua = (req.headers.get("user-agent") ?? "").slice(0, 400);
    // Silently accept but skip obvious bots and empty UAs.
    if (!ua || BOT_RE.test(ua)) {
      return NextResponse.json({ ok: true });
    }

    const path =
      typeof body.path === "string" && body.path ? body.path.slice(0, 300) : "/";
    let referrer =
      typeof body.referrer === "string" && body.referrer
        ? body.referrer.slice(0, 400)
        : null;
    // Drop same-origin referrers — they're just internal navigation noise.
    if (referrer) {
      try {
        if (new URL(referrer).host === url.host) referrer = null;
      } catch {
        /* keep opaque referrer strings as-is */
      }
    }

    // --- Stable, consent-gated visitor id ---
    // Opt-out model mirrors lib/consent.ts marketingAllowed(): allowed unless the
    // visitor EXPLICITLY chose "necessary". No cookie is minted for an opted-out
    // person, so they carry no durable id.
    const consent = readCookie(req, CONSENT_COOKIE);
    const idAllowed = consent !== "necessary";
    let visitorId: string | null = null;
    let setVidCookie: string | null = null;
    if (idAllowed) {
      const existing = readCookie(req, VID_COOKIE);
      visitorId = existing && /^[A-Za-z0-9-]{8,64}$/.test(existing) ? existing : randomUUID();
      if (!existing) setVidCookie = visitorId;
    }

    await db.visit.create({
      data: {
        ip,
        path,
        referrer,
        ua,
        kind,
        visitorId,
        sessionId: cleanId(body.sessionId),
        pvid: cleanId(body.pvid),
        isEntry: body.isEntry === true,
        utmSource: cleanUtm(body.utmSource),
        utmMedium: cleanUtm(body.utmMedium),
        utmCampaign: cleanUtm(body.utmCampaign),
      },
    });

    const res = NextResponse.json({ ok: true });
    if (setVidCookie) {
      res.cookies.set(VID_COOKIE, setVidCookie, {
        httpOnly: true,
        sameSite: "lax",
        secure: true,
        path: "/",
        maxAge: VID_MAX_AGE,
      });
    }
    return res;
  } catch {
    // Never surface capture failures to the page.
  }
  return NextResponse.json({ ok: true });
}

"use client";

import { useEffect, useRef } from "react";
import { usePathname } from "next/navigation";

/**
 * Invisible page-view beacon. Mount once in the marketing layout (kind default)
 * and once in the portal Shell with `kind="portal"`. On every client-side route
 * change it fires a best-effort POST to /api/track. Rapid repeats of the same
 * path are de-duped within the tab via sessionStorage so React strict-mode
 * double-mounts and quick back/forward navigation don't double-count.
 *
 * Beyond the raw pageview it now also captures the behaviour the audience/funnel
 * dashboard needs, all client-side and cookie-free here (the durable, consent-gated
 * visitor id is minted server-side in /api/track):
 *  - a per-TAB `sessionId` (sessionStorage, restarts after 30 min idle) so pageviews
 *    group into sessions for "avg time on site" and bounce rate,
 *  - an `isEntry` flag on the first pageview of a session (the landing page),
 *  - `utm_*` params off the landing URL, remembered for the whole session so every
 *    page attributes back to the ad/campaign that brought the visitor,
 *  - a per-pageview id (`pvid`) plus a dwell-time "close" beacon fired on navigation
 *    away and on pagehide, so each pageview gets a real time-on-page.
 */
export default function VisitTracker({ kind = "marketing" }: { kind?: "marketing" | "portal" }) {
  const pathname = usePathname();
  // The currently-open pageview whose dwell time we still owe a close beacon for.
  const openRef = useRef<{ pvid: string; start: number } | null>(null);

  useEffect(() => {
    if (typeof window === "undefined") return;
    const path = pathname || window.location.pathname || "/";

    // Dedupe: skip if we already tracked this exact path within the last 30s.
    const dkey = `nx_track:${kind}:${path}`;
    try {
      const last = Number(window.sessionStorage.getItem(dkey) ?? 0);
      if (Date.now() - last < 30_000) return;
      window.sessionStorage.setItem(dkey, String(Date.now()));
    } catch {
      /* private mode / storage disabled — just proceed without dedupe */
    }

    // --- Session id (per tab, 30-min idle window) + entry detection ---
    const SESSION_IDLE_MS = 30 * 60_000;
    let sessionId = "";
    let isEntry = false;
    let utm: { source?: string; medium?: string; campaign?: string } = {};
    try {
      const now = Date.now();
      const prevId = window.sessionStorage.getItem("nx_sid");
      const prevTs = Number(window.sessionStorage.getItem("nx_sid_ts") ?? 0);
      if (prevId && now - prevTs < SESSION_IDLE_MS) {
        sessionId = prevId;
        // Carry the session's captured campaign forward to every page.
        try {
          utm = JSON.parse(window.sessionStorage.getItem("nx_utm") ?? "{}");
        } catch {
          /* ignore malformed */
        }
      } else {
        // Fresh session: this pageview is the entry/landing hit.
        sessionId = genId();
        isEntry = true;
        const qs = new URLSearchParams(window.location.search);
        const src = qs.get("utm_source") ?? undefined;
        const med = qs.get("utm_medium") ?? undefined;
        const camp = qs.get("utm_campaign") ?? undefined;
        utm = {
          ...(src ? { source: src.slice(0, 120) } : {}),
          ...(med ? { medium: med.slice(0, 120) } : {}),
          ...(camp ? { campaign: camp.slice(0, 120) } : {}),
        };
        window.sessionStorage.setItem("nx_sid", sessionId);
        window.sessionStorage.setItem("nx_utm", JSON.stringify(utm));
      }
      window.sessionStorage.setItem("nx_sid_ts", String(now));
    } catch {
      // Storage disabled — still track the pageview, just without session grouping.
      sessionId = genId();
    }

    // Close out the previous pageview's dwell before opening this one (SPA nav).
    closeOpen();

    const pvid = genId();
    openRef.current = { pvid, start: Date.now() };

    try {
      fetch(`/api/track?k=${kind}`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          path,
          referrer: document.referrer || null,
          sessionId,
          pvid,
          isEntry,
          utmSource: utm.source ?? null,
          utmMedium: utm.medium ?? null,
          utmCampaign: utm.campaign ?? null,
        }),
        keepalive: true,
      }).catch(() => {});
    } catch {
      /* fire-and-forget; never disrupt the page */
    }
    // pathname is the dependency; helpers are stable closures.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pathname, kind]);

  // Close the last open pageview when the tab is actually going away.
  useEffect(() => {
    if (typeof window === "undefined") return;
    const onHide = () => closeOpen();
    const onVis = () => {
      if (document.visibilityState === "hidden") closeOpen();
    };
    window.addEventListener("pagehide", onHide);
    document.addEventListener("visibilitychange", onVis);
    return () => {
      window.removeEventListener("pagehide", onHide);
      document.removeEventListener("visibilitychange", onVis);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [kind]);

  /** Send the dwell time for the currently-open pageview, once. */
  function closeOpen() {
    const open = openRef.current;
    if (!open) return;
    openRef.current = null;
    const dur = Date.now() - open.start;
    if (dur < 250) return; // ignore instant bounces / strict-mode churn
    const body = JSON.stringify({ close: true, pvid: open.pvid, dur });
    try {
      // sendBeacon survives unload; fall back to keepalive fetch.
      if (navigator.sendBeacon) {
        navigator.sendBeacon(`/api/track?k=${kind}`, new Blob([body], { type: "application/json" }));
      } else {
        fetch(`/api/track?k=${kind}`, {
          method: "POST",
          headers: { "content-type": "application/json" },
          body,
          keepalive: true,
        }).catch(() => {});
      }
    } catch {
      /* best-effort */
    }
  }

  return null;
}

/** Small random id; prefers crypto.randomUUID, falls back for old browsers. */
function genId(): string {
  try {
    if (typeof crypto !== "undefined" && crypto.randomUUID) return crypto.randomUUID();
  } catch {
    /* ignore */
  }
  return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
}
