        if (payload.typ === "imp" && payload.adminId === real.id && typeof payload.sub === "string") {
          const target = await db.user.findUnique({ where: { id: payload.sub } });
          // The token outlives the checks `impersonateUser` made when it minted
          // it (2h), so they are re-made here against the CURRENT row rather
          // than trusted from the past:
