import Link from "next/link";
import { notFound } from "next/navigation";
import { requireArea } from "@/lib/rbac";
import { db } from "@/lib/db";
import { StatCard, StatusDot, Badge, fmtMoney, timeAgo } from "@/components/ui/primitives";
import { SuspendUserButton, CreditForm, SuspendServerButton, RevenueExcludeToggle } from "@/components/AdminControls";
import { ImpersonateButton } from "@/components/admin/ImpersonateButton";
import { CustomerNotes } from "@/components/admin/CustomerNotes";
import { fleetMrrCents, actingAdminId, detailWithoutActor } from "@/lib/admin-metrics";

export const dynamic = "force-dynamic";

export default async function AdminUserDetail({ params }: { params: Promise<{ id: string }> }) {
  /*
   * `clients` is a SUPPORT area (lib/rbac.ts AREA_ROLES), but every write control
   * on this page — Credit, Impersonate, Suspend user, Suspend server — is behind
   * an action that calls `requireAdmin()`. A SUPPORT agent was therefore shown an
   * "Impersonate" button beside every customer, and a "Suspend" button beside
   * every server, and got an unhandled FORBIDDEN throw on click: no error state,
   * just a blank error boundary.
   *
   * A control a role cannot use is not a permission, it is a promise the server
   * refuses to keep. The RBAC decision stays exactly where it is enforced — inside
   * the action — and the page simply stops rendering what it knows will be
   * refused. Nothing is granted here; controls are only ever removed.
   */
  const me = await requireArea("clients");
  const canAct = me.role === "ADMIN";
  const { id } = await params;

  const user = await db.user.findUnique({
    where: { id },
    include: {
      servers: {
        include: { plan: true, gamePlan: { select: { priceCents: true, termMonths: true } } },
        orderBy: { createdAt: "desc" },
      },
      // Shared web hosting accounts (HostingAccount) — the second product line the
      // profile previously ignored entirely.
      hostingAccounts: {
        include: {
          plan: { select: { name: true, priceCents: true } },
          node: { select: { name: true } },
        },
        orderBy: { createdAt: "desc" },
      },
      // Business email subscriptions (EmailSubscription) with their mailbox count.
      emailSubscriptions: {
        include: {
          emailPlan: { select: { name: true, priceCents: true, termMonths: true } },
          _count: { select: { mailboxes: true } },
        },
        orderBy: { createdAt: "desc" },
      },
      transactions: { orderBy: { createdAt: "desc" }, take: 20 },
      invoices: { orderBy: { createdAt: "desc" } },
      tickets: { orderBy: { updatedAt: "desc" } },
      domains: { orderBy: { createdAt: "desc" } },
      // Teams — orgs this customer owns, and orgs they belong to.
      ownedOrgs: { include: { _count: { select: { members: true } } }, orderBy: { createdAt: "desc" } },
      memberships: { include: { org: { select: { id: true, name: true } } } },
      // Internal ops notes about this customer.
      customerNotes: {
        include: { author: { select: { name: true, email: true } } },
        orderBy: { createdAt: "desc" },
      },
      auditLogs: { orderBy: { createdAt: "desc" }, take: 15 },
      _count: {
        select: {
          sshKeys: true,
          notifications: true,
          hostingAccounts: true,
          emailSubscriptions: true,
          domains: true,
          invoices: true,
          apiTokens: true,
        },
      },
    },
  });
  if (!user) notFound();

  const activeServers = user.servers.filter((s) => s.status !== "DELETING");
  const activeHosting = user.hostingAccounts.filter((h) => h.status !== "DELETING");
  const activeEmail = user.emailSubscriptions.filter((e) => e.status !== "CANCELLED");
  // Priced the way the billing engine prices — game plans at their flat rate,
  // term prices per month, suspended machines at zero. See `serverMonthlyCents`.
  const mrrCents = fleetMrrCents(activeServers);
  const openTickets = user.tickets.filter((t) => t.status !== "CLOSED").length;
  // Lifetime spend = net of what actually got paid (invoice total minus any
  // refunds against it). OPEN/VOID invoices are not spend.
  const paidInvoices = user.invoices.filter((i) => i.status === "PAID");
  const lifetimeSpendCents = paidInvoices.reduce((s, i) => s + (i.amountCents - i.refundedCents), 0);
  const openInvoices = user.invoices.filter((i) => i.status === "OPEN");
  const openInvoiceCents = openInvoices.reduce((s, i) => s + i.amountCents, 0);

  // Real actor for any activity row taken while an admin was impersonating.
  const actorIds = [...new Set(user.auditLogs.map((a) => actingAdminId(a.detail)).filter(Boolean))] as string[];
  const actors = new Map(
    (actorIds.length > 0
      ? await db.user.findMany({ where: { id: { in: actorIds } }, select: { id: true, email: true } })
      : []
    ).map((u) => [u.id, u.email]),
  );

  // Client info — where they sign in from and what they look at, derived from the
  // Visit log + the login audit. All read-only; no new schema.
  const [visits, lastLoginRow] = await Promise.all([
    db.visit.findMany({
      where: { userId: id },
      orderBy: { createdAt: "desc" },
      take: 60,
      select: { ip: true, country: true, city: true, path: true, kind: true, createdAt: true },
    }),
    db.auditLog.findFirst({ where: { userId: id, action: "user.login" }, orderBy: { createdAt: "desc" }, select: { createdAt: true } }),
  ]);
  const ipMap = new Map<string, { country: string | null; city: string | null; lastSeen: Date }>();
  for (const v of visits) if (!ipMap.has(v.ip)) ipMap.set(v.ip, { country: v.country, city: v.city, lastSeen: v.createdAt });
  const signInIps = [...ipMap.entries()].slice(0, 8);
  const recentPages = visits.filter((v) => v.kind === "portal").slice(0, 12);
  const country = visits.find((v) => v.country)?.country ?? null;
  const lastLogin = lastLoginRow?.createdAt ?? null;

  return (
    <div className="space-y-6">
      {/* Profile header */}
      <div className="card flex flex-wrap items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className="flex h-14 w-14 items-center justify-center rounded-2xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 text-xl font-bold text-brand-300">
            {user.name.slice(0, 1).toUpperCase()}
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h1 className="text-xl font-bold tracking-tight">{user.name}</h1>
              <Badge tone={user.role === "ADMIN" ? "brand" : "slate"}>{user.role.toLowerCase()}</Badge>
              {user.suspended && <Badge tone="red">suspended</Badge>}
            </div>
            <p className="mt-0.5 text-sm text-slate-400">
              {user.email} · joined {user.createdAt.toISOString().slice(0, 10)} · {user._count.sshKeys} SSH key
              {user._count.sshKeys === 1 ? "" : "s"} · {user._count.notifications} notification
              {user._count.notifications === 1 ? "" : "s"} sent
            </p>
          </div>
        </div>
        <div className="flex flex-wrap items-center gap-2">
          {canAct ? (
            <>
              <CreditForm userId={user.id} />
              {user.role !== "ADMIN" && <ImpersonateButton userId={user.id} email={user.email} />}
              {user.role !== "ADMIN" && <SuspendUserButton userId={user.id} suspended={user.suspended} />}
              <RevenueExcludeToggle userId={user.id} excluded={user.excludeFromRevenue} />
            </>
          ) : (
            <p className="text-xs text-slate-500">
              Read-only — crediting, impersonating and suspending require an admin account.
            </p>
          )}
        </div>
      </div>

      {/* Client info — sign-in IPs, location, last login, recent pages */}
      <div className="card">
        <h2 className="mb-3 font-semibold">Client info</h2>
        <div className="grid gap-5 sm:grid-cols-2">
          <div className="space-y-2 text-sm">
            <p className="text-slate-400">Joined <span className="text-slate-200">{user.createdAt.toISOString().slice(0, 10)}</span></p>
            <p className="text-slate-400">Last login <span className="text-slate-200">{lastLogin ? timeAgo(lastLogin) : "—"}</span></p>
            <p className="text-slate-400">Location <span className="text-slate-200">{country ?? "unknown"}</span></p>
            <p className="text-slate-400">
              Email verified{" "}
              {user.emailVerifiedAt ? (
                <Badge tone="green">yes</Badge>
              ) : (
                <Badge tone="amber">no</Badge>
              )}
            </p>
            <p className="text-slate-400">
              2FA{" "}
              {user.totpEnabled ? <Badge tone="green">on</Badge> : <Badge tone="slate">off</Badge>}
            </p>
            <p className="text-slate-400">Lifetime spend <span className="text-slate-200">{fmtMoney(lifetimeSpendCents)}</span> <span className="text-xs text-slate-500">· {user._count.invoices} invoice{user._count.invoices === 1 ? "" : "s"}</span></p>
            <p className="text-slate-400">API tokens <span className="text-slate-200">{user._count.apiTokens}</span></p>
            {(user.ownedOrgs.length > 0 || user.memberships.length > 0) && (
              <div>
                <p className="mb-1 text-slate-400">Teams</p>
                <div className="space-y-1">
                  {user.ownedOrgs.map((o) => (
                    <p key={o.id} className="text-xs text-slate-300">
                      {o.name} <span className="text-slate-500">· owner · {o._count.members} member{o._count.members === 1 ? "" : "s"}</span>
                    </p>
                  ))}
                  {user.memberships.map((m) => (
                    <p key={m.id} className="text-xs text-slate-300">
                      {m.org.name} <span className="text-slate-500">· {m.role.toLowerCase()}</span>
                    </p>
                  ))}
                </div>
              </div>
            )}
            <div>
              <p className="mb-1 text-slate-400">Sign-in IPs</p>
              {signInIps.length === 0 ? (
                <p className="text-xs text-slate-500">No recorded sessions yet.</p>
              ) : (
                <div className="space-y-1">
                  {signInIps.map(([ip, meta]) => (
                    <p key={ip} className="font-mono text-xs text-slate-300">
                      {ip} <span className="text-slate-500">· {[meta.city, meta.country].filter(Boolean).join(", ") || "—"} · {timeAgo(meta.lastSeen)}</span>
                    </p>
                  ))}
                </div>
              )}
            </div>
          </div>
          <div>
            <p className="mb-1 text-sm text-slate-400">Recent pages</p>
            {recentPages.length === 0 ? (
              <p className="text-xs text-slate-500">No portal page views recorded.</p>
            ) : (
              <div className="max-h-52 space-y-1 overflow-y-auto pr-1">
                {recentPages.map((v, i) => (
                  <p key={i} className="truncate text-xs text-slate-300">{v.path} <span className="text-slate-500">· {timeAgo(v.createdAt)}</span></p>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        <StatCard
          label="Wallet balance"
          value={fmtMoney(user.balanceCents)}
          delta={openInvoiceCents > 0 ? `${fmtMoney(openInvoiceCents)} unpaid` : undefined}
        />
        <StatCard label="Monthly spend" value={mrrCents > 0 ? `${fmtMoney(mrrCents)}/mo` : "$0.00"} delta="committed MRR" />
        <StatCard label="Lifetime spend" value={fmtMoney(lifetimeSpendCents)} delta={`${user._count.invoices} invoices`} />
        <StatCard
          label="Services"
          value={String(activeServers.length + activeHosting.length + activeEmail.length + user._count.domains)}
          delta={`${activeServers.length} vps · ${activeHosting.length} hosting · ${activeEmail.length} email · ${user._count.domains} domains`}
        />
      </div>
      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        <StatCard label="Servers" value={String(activeServers.length)} />
        <StatCard label="Web hosting" value={String(activeHosting.length)} />
        <StatCard label="Business email" value={String(activeEmail.length)} />
        <StatCard
          label="Tickets"
          value={String(user.tickets.length)}
          delta={openTickets > 0 ? `${openTickets} open` : "none open"}
          deltaGood={openTickets === 0}
        />
      </div>

      {/* Servers */}
      <div className="card p-0">
        <h2 className="px-5 pt-5 font-semibold">Servers</h2>
        {user.servers.length === 0 ? (
          <p className="px-5 py-8 text-sm text-slate-500">No servers yet.</p>
        ) : (
          <div className="overflow-x-auto pt-3">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Hostname</th>
                  <th>Status</th>
                  <th>Plan</th>
                  <th>IP</th>
                  <th>Expires</th>
                  <th className="text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {user.servers.map((s) => (
                  <tr key={s.id}>
                    <td>
                      <Link href={`/admin/servers/${s.id}`} className="font-medium hover:text-brand-300">
                        {s.hostname}
                      </Link>
                      {s.isFree && (
                        <span className="ml-2">
                          <Badge tone="green">free</Badge>
                        </span>
                      )}
                    </td>
                    <td>
                      <StatusDot status={s.status} />
                    </td>
                    <td>
                      {s.plan.name}
                      {!s.isFree && <span className="text-xs text-slate-500"> · {fmtMoney(s.plan.priceCents)}/mo</span>}
                    </td>
                    <td className="font-mono text-xs">{s.ipAddress ?? "—"}</td>
                    <td className="text-xs">
                      {s.isFree ? "never" : s.expiresAt ? s.expiresAt.toISOString().slice(0, 10) : "—"}
                    </td>
                    <td className="text-right">
                      {canAct && s.status !== "DELETING" && (
                        <SuspendServerButton serverId={s.id} suspended={s.status === "SUSPENDED"} />
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Shared web hosting */}
      <div className="card p-0">
        <div className="flex items-center justify-between px-5 pt-5">
          <h2 className="font-semibold">Web hosting</h2>
          <Link href="/admin/hosting" className="text-xs text-slate-400 hover:text-brand-300">Manage →</Link>
        </div>
        {user.hostingAccounts.length === 0 ? (
          <p className="px-5 py-8 text-sm text-slate-500">No hosting accounts.</p>
        ) : (
          <div className="overflow-x-auto pt-3">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Domain</th>
                  <th>Status</th>
                  <th>Plan</th>
                  <th>Node</th>
                  <th>SSL</th>
                  <th className="text-right">Expires</th>
                </tr>
              </thead>
              <tbody>
                {user.hostingAccounts.map((h) => (
                  <tr key={h.id}>
                    <td className="font-medium">
                      {h.primaryDomain}
                      <span className="ml-2 font-mono text-xs text-slate-500">{h.username}</span>
                    </td>
                    <td>
                      <StatusDot status={h.status} />
                    </td>
                    <td>
                      {h.plan.name}
                      <span className="text-xs text-slate-500"> · {fmtMoney(h.plan.priceCents)}/mo</span>
                    </td>
                    <td className="text-xs text-slate-400">{h.node.name}</td>
                    <td>
                      {h.sslActive ? <Badge tone="green">active</Badge> : <Badge tone="slate">none</Badge>}
                    </td>
                    <td className="text-right text-xs">
                      {h.expiresAt ? h.expiresAt.toISOString().slice(0, 10) : "—"}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Business email */}
      <div className="card p-0">
        <div className="flex items-center justify-between px-5 pt-5">
          <h2 className="font-semibold">Business email</h2>
          <Link href="/admin/mailboxes" className="text-xs text-slate-400 hover:text-brand-300">Manage →</Link>
        </div>
        {user.emailSubscriptions.length === 0 ? (
          <p className="px-5 py-8 text-sm text-slate-500">No email subscriptions.</p>
        ) : (
          <div className="overflow-x-auto pt-3">
            <table className="table-shell">
              <thead>
                <tr>
                  <th>Domain</th>
                  <th>Status</th>
                  <th>Plan</th>
                  <th>Mailboxes</th>
                  <th>Verified</th>
                  <th className="text-right">Expires</th>
                </tr>
              </thead>
              <tbody>
                {user.emailSubscriptions.map((e) => (
                  <tr key={e.id}>
                    <td className="font-medium">{e.domainName}</td>
                    <td>
                      <StatusDot status={e.status} />
                    </td>
                    <td>
                      {e.emailPlan.name}
                      <span className="text-xs text-slate-500"> · {fmtMoney(e.emailPlan.priceCents)}/{e.emailPlan.termMonths === 1 ? "mo" : `${e.emailPlan.termMonths}mo`}</span>
                    </td>
                    <td className="text-xs">{e._count.mailboxes}</td>
                    <td>
                      {e.verified ? <Badge tone="green">yes</Badge> : <Badge tone="amber">no</Badge>}
                    </td>
                    <td className="text-right text-xs">
                      {e.expiresAt ? e.expiresAt.toISOString().slice(0, 10) : "—"}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <div className="grid gap-4 xl:grid-cols-2">
        {/* Transactions */}
        <div className="card p-0">
          <h2 className="px-5 pt-5 font-semibold">Wallet transactions</h2>
          {user.transactions.length === 0 ? (
            <p className="px-5 py-8 text-sm text-slate-500">No transactions.</p>
          ) : (
            <div className="overflow-x-auto pt-3">
              <table className="table-shell">
                <thead>
                  <tr>
                    <th>Description</th>
                    <th>When</th>
                    <th className="text-right">Amount</th>
                  </tr>
                </thead>
                <tbody>
                  {user.transactions.map((t) => (
                    <tr key={t.id}>
                      <td className="max-w-64 truncate">{t.description}</td>
                      <td className="text-xs text-slate-400">{timeAgo(t.createdAt)}</td>
                      <td
                        className={`text-right font-medium ${t.amountCents < 0 ? "text-red-400" : "text-emerald-400"}`}
                      >
                        {t.amountCents < 0 ? "−" : "+"}
                        {fmtMoney(Math.abs(t.amountCents))}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Tickets */}
        <div className="card p-0">
          <h2 className="px-5 pt-5 font-semibold">Support tickets</h2>
          {user.tickets.length === 0 ? (
            <p className="px-5 py-8 text-sm text-slate-500">No tickets.</p>
          ) : (
            <div className="overflow-x-auto pt-3">
              <table className="table-shell">
                <thead>
                  <tr>
                    <th>Subject</th>
                    <th>Priority</th>
                    <th>Status</th>
                    <th className="text-right">Updated</th>
                  </tr>
                </thead>
                <tbody>
                  {user.tickets.map((t) => (
                    <tr key={t.id}>
                      <td>
                        <Link href={`/admin/support/${t.id}`} className="font-medium hover:text-brand-300">
                          {t.subject}
                        </Link>
                      </td>
                      <td>
                        <Badge
                          tone={
                            t.priority === "URGENT"
                              ? "red"
                              : t.priority === "HIGH"
                                ? "amber"
                                : t.priority === "NORMAL"
                                  ? "brand"
                                  : "slate"
                          }
                        >
                          {t.priority.toLowerCase()}
                        </Badge>
                      </td>
                      <td>
                        <StatusDot status={t.status} />
                      </td>
                      <td className="text-right text-xs text-slate-400">{timeAgo(t.updatedAt)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Domains */}
        <div className="card p-0">
          <h2 className="px-5 pt-5 font-semibold">Domains</h2>
          {user.domains.length === 0 ? (
            <p className="px-5 py-8 text-sm text-slate-500">No domains.</p>
          ) : (
            <div className="overflow-x-auto pt-3">
              <table className="table-shell">
                <thead>
                  <tr>
                    <th>Domain</th>
                    <th>Status</th>
                    <th className="text-right">Expires</th>
                  </tr>
                </thead>
                <tbody>
                  {user.domains.map((d) => (
                    <tr key={d.id}>
                      <td className="font-medium">{d.name}</td>
                      <td>
                        <Badge tone={d.status === "ACTIVE" ? "green" : d.status === "FAILED" ? "red" : "amber"}>
                          {d.status.toLowerCase()}
                        </Badge>
                      </td>
                      <td className="text-right text-xs">
                        {d.expiresAt ? d.expiresAt.toISOString().slice(0, 10) : "—"}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Invoices */}
        <div className="card p-0">
          <div className="flex items-center justify-between px-5 pt-5">
            <h2 className="font-semibold">Invoices</h2>
            <Link href="/admin/invoices" className="text-xs text-slate-400 hover:text-brand-300">All →</Link>
          </div>
          {user.invoices.length === 0 ? (
            <p className="px-5 py-8 text-sm text-slate-500">No invoices.</p>
          ) : (
            <div className="overflow-x-auto pt-3">
              <table className="table-shell">
                <thead>
                  <tr>
                    <th>#</th>
                    <th>Description</th>
                    <th>Status</th>
                    <th className="text-right">Amount</th>
                  </tr>
                </thead>
                <tbody>
                  {user.invoices.slice(0, 12).map((inv) => (
                    <tr key={inv.id}>
                      <td>
                        <Link href={`/admin/invoices/${inv.id}`} className="font-mono text-xs hover:text-brand-300">
                          #{inv.number}
                        </Link>
                      </td>
                      <td className="max-w-56 truncate text-xs">{inv.description}</td>
                      <td>
                        <Badge
                          tone={
                            inv.status === "PAID"
                              ? "green"
                              : inv.status === "OPEN"
                                ? "amber"
                                : inv.status === "REFUNDED"
                                  ? "brand"
                                  : "slate"
                          }
                        >
                          {inv.status.toLowerCase()}
                        </Badge>
                      </td>
                      <td className="text-right font-medium">{fmtMoney(inv.amountCents)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* Audit trail */}
        <div className="card p-0">
          <h2 className="px-5 pt-5 font-semibold">Recent activity</h2>
          {user.auditLogs.length === 0 ? (
            <p className="px-5 py-8 text-sm text-slate-500">No recorded activity.</p>
          ) : (
            <ul className="divide-y divide-white/[0.05] px-5 py-2">
              {user.auditLogs.map((a) => {
                // These rows are scoped to the CUSTOMER, so an admin action taken
                // while impersonating them lands here reading exactly like
                // something the customer did. Name the admin.
                const asAdmin = actingAdminId(a.detail);
                const detail = asAdmin ? detailWithoutActor(a.detail) : a.detail;
                return (
                  <li key={a.id} className="flex items-baseline justify-between gap-3 py-2.5 text-sm">
                    <div className="min-w-0">
                      <span className="font-medium">{a.action}</span>
                      {detail && <span className="ml-2 truncate text-xs text-slate-500">{detail}</span>}
                      {asAdmin && (
                        <span className="ml-2">
                          <Badge tone="amber">by {actors.get(asAdmin) ?? asAdmin}</Badge>
                        </span>
                      )}
                    </div>
                    <span className="shrink-0 text-xs text-slate-500">{timeAgo(a.createdAt)}</span>
                  </li>
                );
              })}
            </ul>
          )}
        </div>
      </div>

      {/* Internal admin notes */}
      <CustomerNotes userId={user.id} notes={user.customerNotes} canEdit={canAct} />
    </div>
  );
}

import { requireArea } from "@/lib/rbac";
import { PageHeader, StatCard } from "@/components/ui/primitives";
import {
  liveVisitors,
  todayViews,
  viewsInWindow,
  uniqueVisitors,
  topReferrers,
  topCountries,
  topCities,
  recentVisits,
  globePoints,
  visitFeed,
  visitFeedCount,
  type FeedDir,
  type FeedKind,
} from "@/lib/analytics";
import VisitorGlobe from "@/components/admin/VisitorGlobe";
import { RankedList, RecentVisitsTable, TrafficFeedTable } from "@/components/admin/VisitorStats";
import { ExcludeIpPanel } from "@/components/admin/ExcludeIpPanel";
import { TrafficFeedFilter } from "@/components/admin/TrafficFeedFilter";
import { analyticsExcludeState } from "@/lib/actions-analytics";

export const dynamic = "force-dynamic";

const FEED_LIMIT = 200;

export default async function VisitorsPage({
  searchParams,
}: {
  searchParams: Promise<{ from?: string; to?: string; kind?: string; dir?: string }>;
}) {
  await requireArea("analytics");

  const sp = await searchParams;
  const from = (sp.from ?? "").trim();
  const to = (sp.to ?? "").trim();
  const kind: FeedKind = sp.kind === "marketing" || sp.kind === "portal" ? sp.kind : "all";
  const dir: FeedDir = sp.dir === "asc" ? "asc" : "desc";
  const feedFilter = { from, to, kind, dir, limit: FEED_LIMIT };

  const [
    live,
    today,
    views7d,
    unique7d,
    referrers,
    countries,
    cities,
    recents,
    points,
    excludeState,
    feed,
    feedTotal,
  ] = await Promise.all([
    liveVisitors(5),
    todayViews(),
    viewsInWindow(7),
    uniqueVisitors(7),
    topReferrers(7, 8),
    topCountries(30, 8),
    topCities(30, 8),
    recentVisits(40),
    globePoints(7, 300),
    analyticsExcludeState(),
    visitFeed(feedFilter),
    visitFeedCount(feedFilter),
  ]);

  return (
    <div className="space-y-6">
      <PageHeader
        title="Visitor analytics"
        sub="Live traffic across the marketing site and portals, geo-located best-effort."
      />

      <ExcludeIpPanel myIp={excludeState.myIp} excluded={excludeState.excluded} />

      <div className="grid grid-cols-2 gap-4 xl:grid-cols-4">
        <StatCard
          label="Live visitors · 5 min"
          value={String(live)}
          delta={live === 0 ? "quiet right now" : "distinct IPs active now"}
          deltaGood={live > 0}
        />
        <StatCard label="Views today" value={String(today)} delta="since midnight" />
        <StatCard label="Views · 7d" value={String(views7d)} delta="trailing 7 days" />
        <StatCard label="Unique visitors · 7d" value={String(unique7d)} delta="distinct IPs, 7d" />
      </div>

      <div className="grid gap-4 xl:grid-cols-3">
        <div className="xl:col-span-2">
          <VisitorGlobe points={points} />
        </div>
        <div className="space-y-4">
          <RankedList
            title="Top countries"
            sub="Geocoded visits · last 30 days"
            items={countries}
            emptyLabel="No geocoded visits yet."
          />
          <RankedList
            title="Top cities"
            sub="Geocoded visits · last 30 days"
            items={cities}
            emptyLabel="No geocoded visits yet."
          />
        </div>
      </div>

      <div className="grid gap-4 xl:grid-cols-3">
        <RankedList
          title="Top referrers"
          sub="External sources · last 7 days"
          items={referrers}
          emptyLabel="No external referrers yet — traffic is direct."
        />
        <div className="xl:col-span-2">
          <RecentVisitsTable visits={recents} />
        </div>
      </div>

      <TrafficFeedFilter from={from} to={to} kind={kind} dir={dir} />
      <TrafficFeedTable visits={feed} total={feedTotal} shown={feed.length} />
    </div>
  );
}

