/** A compact ranked list ("top referrers", "top countries", …) with count bars. */
export function RankedList({
  title,
  sub,
  items,
  emptyLabel,
}: {
  title: string;
  sub?: string;
  items: Counted[];
  emptyLabel: string;
}) {
  const max = items.reduce((m, i) => Math.max(m, i.count), 0) || 1;
  return (
    <div className="card">
      <h2 className="font-semibold">{title}</h2>
      {sub && <p className="mt-1 text-xs text-slate-500">{sub}</p>}
      {items.length === 0 ? (
        <p className="py-6 text-sm text-slate-500">{emptyLabel}</p>
      ) : (
        <ul className="mt-3 space-y-2.5">
          {items.map((it) => (
            <li key={it.label}>
              <div className="flex items-center justify-between text-sm">
                <span className="truncate pr-3 text-slate-200">{it.label}</span>
                <span className="tabular-nums text-slate-400">{it.count}</span>
              </div>
              <div className="mt-1 h-1.5 overflow-hidden rounded-full bg-white/[0.05]">
                <div
                  className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500"
                  style={{ width: `${Math.max(6, (it.count / max) * 100)}%` }}
                />
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

