import { db } from "@/lib/db";
import { getSetting } from "@/lib/settings";

/**
 * Plain (non-action) aggregation helpers for the visitor-analytics admin page.
 * These are read-only Prisma queries over the `Visit` table. Everything is
 * scoped to short recent windows and small `take` limits so the page stays
 * cheap even as the visit log grows.
 */

const DAY = 86_400_000;

/** IPs the admin has chosen to exclude from analytics (their own IP, office IP,
 *  a noisy bot) so the numbers reflect ACTUAL public traffic. Stored as a
 *  comma-separated setting. */
export async function excludedIps(): Promise<string[]> {
  const raw = (await getSetting("analytics_excluded_ips")) ?? "";
  return raw.split(",").map((s) => s.trim()).filter(Boolean);
}

/** Prisma where-fragment dropping excluded IPs. Empty object when none are set,
 *  so it spreads harmlessly into any `where`. */
async function ipEx(): Promise<{ ip?: { notIn: string[] } }> {
  const e = await excludedIps();
  return e.length ? { ip: { notIn: e } } : {};
}

/** Distinct client IPs seen in the last `minutes` — our "live visitors now" gauge. */
export async function liveVisitors(minutes = 5): Promise<number> {
  const since = new Date(Date.now() - minutes * 60_000);
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: since }, ...(await ipEx()) },
    distinct: ["ip"],
    select: { ip: true },
  });
  return rows.length;
}

/** Total page views since local midnight. */
export async function todayViews(): Promise<number> {
  const start = new Date();
  start.setHours(0, 0, 0, 0);
  return db.visit.count({ where: { createdAt: { gte: start }, ...(await ipEx()) } });
}

/** Total page views in the trailing `days` window (default 7d). */
export async function viewsInWindow(days = 7): Promise<number> {
  const since = new Date(Date.now() - days * DAY);
  return db.visit.count({ where: { createdAt: { gte: since }, ...(await ipEx()) } });
}

/** Distinct visitors (by IP) in the trailing `days` window. */
export async function uniqueVisitors(days = 7): Promise<number> {
  const since = new Date(Date.now() - days * DAY);
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: since }, ...(await ipEx()) },
    distinct: ["ip"],
    select: { ip: true },
  });
  return rows.length;
}

/** Reduce a raw referrer URL to a bare hostname for grouping/display. */
export function referrerHost(ref: string | null | undefined): string | null {
  if (!ref) return null;
  try {
    const h = new URL(ref).hostname.replace(/^www\./, "");
    return h || null;
  } catch {
    const trimmed = ref.trim();
    return trimmed ? trimmed.slice(0, 60) : null;
  }
}

export type Counted = { label: string; count: number };

/** Top external referrer hosts over the trailing `days` window. */
export async function topReferrers(days = 7, limit = 8): Promise<Counted[]> {
  const since = new Date(Date.now() - days * DAY);
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: since }, referrer: { not: null }, ...(await ipEx()) },
    select: { referrer: true },
    take: 5000,
    orderBy: { createdAt: "desc" },
  });
  const tally = new Map<string, number>();
  for (const r of rows) {
    const host = referrerHost(r.referrer);
    if (!host) continue;
    tally.set(host, (tally.get(host) ?? 0) + 1);
  }
  return [...tally.entries()]
    .map(([label, count]) => ({ label, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

/** Top countries among geocoded visits over the trailing `days` window. */
export async function topCountries(days = 30, limit = 8): Promise<Counted[]> {
  const since = new Date(Date.now() - days * DAY);
  const grp = await db.visit.groupBy({
    by: ["country"],
    where: { createdAt: { gte: since }, geocoded: true, country: { not: null }, ...(await ipEx()) },
    _count: { _all: true },
  });
  return grp
    .map((g) => ({ label: g.country as string, count: g._count._all }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

/** Top cities among geocoded visits over the trailing `days` window. */
export async function topCities(days = 30, limit = 8): Promise<Counted[]> {
  const since = new Date(Date.now() - days * DAY);
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: since }, geocoded: true, city: { not: null }, ...(await ipEx()) },
    select: { city: true, country: true },
    take: 5000,
    orderBy: { createdAt: "desc" },
  });
  const tally = new Map<string, number>();
  for (const r of rows) {
    const label = r.country ? `${r.city}, ${r.country}` : (r.city as string);
    tally.set(label, (tally.get(label) ?? 0) + 1);
  }
  return [...tally.entries()]
    .map(([label, count]) => ({ label, count }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

export type RecentVisit = {
