// ---- Date-range traffic feed ----
// The dashboard above uses fixed trailing windows; this feed lets the admin pick
// an explicit date range and sort direction, so they can answer "what happened
// on/between these days" rather than only "the last N days". It reuses the same
// IP-exclusion (`ipEx`) as everything else, so hidden IPs stay hidden here too.

export type FeedKind = "all" | "marketing" | "portal";
export type FeedDir = "desc" | "asc";

export type FeedFilter = {
  /** Inclusive start day, `yyyy-mm-dd` (local). */
  from?: string;
  /** Inclusive end day, `yyyy-mm-dd` (local). */
  to?: string;
  kind?: FeedKind;
  /** Sort by date: newest-first (`desc`, default) or oldest-first (`asc`). */
  dir?: FeedDir;
  limit?: number;
};

const YMD = /^\d{4}-\d{2}-\d{2}$/;

/** Start-of-day Date for a `yyyy-mm-dd` string, or undefined if absent/invalid. */
function dayStart(s?: string): Date | undefined {
  if (!s || !YMD.test(s)) return undefined;
  const d = new Date(`${s}T00:00:00`);
  return Number.isNaN(d.getTime()) ? undefined : d;
}

/** End-of-day (inclusive) Date for a `yyyy-mm-dd` string, or undefined. */
function dayEnd(s?: string): Date | undefined {
  if (!s || !YMD.test(s)) return undefined;
  const d = new Date(`${s}T23:59:59.999`);
  return Number.isNaN(d.getTime()) ? undefined : d;
}

/** Build the shared `where` for the feed (date range + kind + IP exclusion). */
async function feedWhere(f: FeedFilter) {
  const gte = dayStart(f.from);
  const lte = dayEnd(f.to);
  const where: {
    ip?: { notIn: string[] };
    kind?: string;
    createdAt?: { gte?: Date; lte?: Date };
  } = { ...(await ipEx()) };
  if (gte || lte) where.createdAt = { ...(gte ? { gte } : {}), ...(lte ? { lte } : {}) };
  if (f.kind && f.kind !== "all") where.kind = f.kind;
  return where;
}

/**
 * Visits within an explicit date range, sorted by date. Capped by `limit`
 * (default 100, hard max 500) so the page stays cheap no matter the range.
 */
export async function visitFeed(f: FeedFilter): Promise<RecentVisit[]> {
  const limit = Math.min(Math.max(f.limit ?? 100, 1), 500);
  return db.visit.findMany({
    where: await feedWhere(f),
    orderBy: { createdAt: f.dir === "asc" ? "asc" : "desc" },
    take: limit,
    select: {
      id: true,
      ip: true,
      path: true,
      referrer: true,
      kind: true,
      country: true,
      region: true,
      city: true,
      createdAt: true,
    },
  });
}

/** Total matching visits for the current feed filter (for the result count). */
export async function visitFeedCount(f: FeedFilter): Promise<number> {
  return db.visit.count({ where: await feedWhere(f) });
}

export type GlobePoint = {
  lat: number;
  lng: number;
  city: string | null;
  country: string | null;
  kind: string;
};

/**
 * Recent geocoded visits with coordinates, for the activity globe. Capped so the
 * canvas stays performant regardless of how much traffic has accumulated.
 */
export async function globePoints(days = 7, limit = 300): Promise<GlobePoint[]> {
  const since = new Date(Date.now() - days * DAY);
  const rows = await db.visit.findMany({
    where: {
      createdAt: { gte: since },
      geocoded: true,
      lat: { not: null },
      lng: { not: null },
      ...(await ipEx()),
    },
    orderBy: { createdAt: "desc" },
    take: limit,
    select: { lat: true, lng: true, city: true, country: true, kind: true },
  });
  return rows.map((r) => ({
    lat: r.lat as number,
    lng: r.lng as number,
    city: r.city,
    country: r.country,
    kind: r.kind,
  }));
}

// ============================================================================
//  Behaviour + funnel — the "what do ad visitors actually DO" layer.
//  Feeds the admin audience dashboard (app/admin/audience). Everything below is
//  read-only, window-scoped and take-capped so it stays cheap as Visit grows.
// ============================================================================

/** Server statuses that mean a real machine was provisioned (funnel "deployed").
 *  Excludes attempts that never became a VM (PENDING/PROVISIONING/ERROR). */
export const DEPLOYED_STATUSES = [
  "RUNNING",
  "STOPPED",
  "SUSPENDED",
  "REINSTALLING",
  "DELETING",
] as const;

/** Cap on how many ids we pass into an `in` clause, to keep queries bounded. */
const ID_CAP = 20_000;

export type NewVsRecurring = {
  /** Distinct identified visitors (by visitorId) active in the window. */
  identified: number;
  /** Of those, first seen ON/AFTER the window start (brand-new). */
  newVisitors: number;
  /** Of those, seen on some earlier day too (recurring). */
  returningVisitors: number;
};

/**
 * New vs recurring visitors over the trailing `days` window. Uses the stable
 * `visitorId` cookie, so it recognises the same person across sessions/IPs —
 * the thing IP-based "unique visitors" cannot do. Opted-out visitors (null
 * visitorId) are simply absent here; they still count in the IP-based uniques.
 */
export async function newVsRecurring(days = 7): Promise<NewVsRecurring> {
  const since = new Date(Date.now() - days * DAY);
  const inWindow = await db.visit.findMany({
    where: { createdAt: { gte: since }, visitorId: { not: null }, ...(await ipEx()) },
    distinct: ["visitorId"],
    select: { visitorId: true },
    take: ID_CAP,
  });
  const ids = inWindow.map((r) => r.visitorId as string);
  if (ids.length === 0) return { identified: 0, newVisitors: 0, returningVisitors: 0 };

  // Which of those visitors we had already seen BEFORE this window = recurring.
  const earlier = await db.visit.findMany({
    where: { visitorId: { in: ids }, createdAt: { lt: since } },
    distinct: ["visitorId"],
    select: { visitorId: true },
    take: ID_CAP,
  });
  const returningVisitors = earlier.length;
  return {
    identified: ids.length,
    newVisitors: ids.length - returningVisitors,
    returningVisitors,
  };
}

export type TimeStats = {
  sessions: number;
  /** Average session dwell (ms) — the "avg time on site" headline. */
  avgSessionMs: number;
  /** Average pageviews per session. */
  avgPageviews: number;
  /** Share of sessions that were a single pageview (0..1). */
  bounceRate: number;
};

/**
 * Session-level engagement over the window: avg time on site, pages/session and
 * bounce rate. Dwell comes from the per-pageview close beacons; a session's time
 * is the sum of its pages' dwell. Sessions with no measured dwell still count for
 * pages/session and bounce, they just contribute 0 to the time average.
 */
export async function visitorTimeStats(days = 7): Promise<TimeStats> {
  const since = new Date(Date.now() - days * DAY);
  const rows = await db.visit.findMany({
    where: { createdAt: { gte: since }, sessionId: { not: null }, ...(await ipEx()) },
    select: { sessionId: true, durationMs: true },
    take: 50_000,
    orderBy: { createdAt: "desc" },
  });
  if (rows.length === 0)
    return { sessions: 0, avgSessionMs: 0, avgPageviews: 0, bounceRate: 0 };

  const perSession = new Map<string, { ms: number; views: number }>();
  for (const r of rows) {
    const key = r.sessionId as string;
    const cur = perSession.get(key) ?? { ms: 0, views: 0 };
    cur.views += 1;
    cur.ms += r.durationMs ?? 0;
    perSession.set(key, cur);
  }
  const sessions = perSession.size;
  let totalMs = 0;
  let totalViews = 0;
  let bounces = 0;
  for (const s of perSession.values()) {
    totalMs += s.ms;
    totalViews += s.views;
    if (s.views <= 1) bounces += 1;
  }
  return {
    sessions,
    avgSessionMs: Math.round(totalMs / sessions),
    avgPageviews: totalViews / sessions,
    bounceRate: bounces / sessions,
  };
}

/** Most-viewed paths over the window (what visitors look at). */
export async function topPages(days = 7, limit = 10): Promise<Counted[]> {
  const since = new Date(Date.now() - days * DAY);
  const grp = await db.visit.groupBy({
    by: ["path"],
    where: { createdAt: { gte: since }, ...(await ipEx()) },
