  });
  return grp
    .map((g) => ({ label: g.path, count: g._count._all }))
    .sort((a, b) => b.count - a.count)
    .slice(0, limit);
}

/** Top landing/entry pages over the window (where sessions begin). */
export async function topEntryPages(days = 7, limit = 8): Promise<Counted[]> {
