/** Country for the current request: proxy header IP → geoip-lite. Null if unknown. */
export function countryFromRequestIp(hdrs: Headers): string | null {
  return countryFromIp(clientIpFromHeaders(hdrs));
}

export type IpLocation = { country: string | null; city: string | null };

/**
 * City + ISO country for an IP from the bundled geoip-lite dataset, or null when
 * unresolvable. This is the client-profile fallback: when a customer has an IP on
 * record but none of their Visit rows were geocoded by the background job yet, we
 * still show *a* location rather than "unknown". Same private/loopback guard as
 * `countryFromIp`. Node runtime only.
 */
export function geoLocateIp(ip: string | null | undefined): IpLocation | null {
  if (!ip) return null;
  if (
    ip === "127.0.0.1" ||
    ip === "::1" ||
    ip.startsWith("10.") ||
    ip.startsWith("192.168.") ||
    /^172\.(1[6-9]|2\d|3[01])\./.test(ip)
  ) {
    return null;
  }
  try {
    const hit = geoip.lookup(ip);
    if (!hit) return null;
    const country = hit.country?.trim().toUpperCase() || null;
    const city = hit.city?.trim() || null;
    if (!country && !city) return null;
    return { country: country && country.length === 2 ? country : country, city };
  } catch {
    return null;
  }
}

