export function geoLocateIp(ip: string | null | undefined): IpLocation | null {
  if (!ip) return null;
  if (
    ip === "127.0.0.1" ||
    ip === "::1" ||
    ip.startsWith("10.") ||
    ip.startsWith("192.168.") ||
    /^172\.(1[6-9]|2\d|3[01])\./.test(ip)
  ) {
    return null;
  }
  try {
    const hit = geoip.lookup(ip);
    if (!hit) return null;
    const cc = hit.country?.trim().toUpperCase() || null;
    const country = cc && cc.length === 2 ? cc : null;
    const city = hit.city?.trim() || null;
    if (!country && !city) return null;
    return { country, city };
  } catch {
    return null;
  }
}

