/**
 * Attach the owning account to each visit row. Visit has only a `userId` scalar
 * (no relation), so we batch-resolve the distinct ids in one query rather than
 * N+1. Rows with no userId (anonymous) get `account: null`.
 */
async function withAccounts(
  rows: (Omit<RecentVisit, "account"> & { userId: string | null })[],
): Promise<RecentVisit[]> {
  const ids = [...new Set(rows.map((r) => r.userId).filter(Boolean))] as string[];
  const users =
    ids.length > 0
      ? await db.user.findMany({ where: { id: { in: ids } }, select: { id: true, name: true, email: true } })
      : [];
  const byId = new Map(users.map((u) => [u.id, u]));
  return rows.map(({ userId, ...r }) => ({ ...r, account: userId ? byId.get(userId) ?? null : null }));
}

