export type PerKindTime = {
  /** Average dwell (ms) over pageviews that HAVE a measured duration. */
  avgMs: number;
  /** How many pageviews contributed (non-null durationMs) — the sample size. */
  samples: number;
};

export type TimePerPageByKind = {
  marketing: PerKindTime;
  portal: PerKindTime;
  overall: PerKindTime;
};

/**
 * Average time-on-page split by visit kind (marketing vs portal). This is the
 * per-PAGEVIEW average (Σ durationMs / count of pages with a duration), distinct
 * from `visitorTimeStats.avgSessionMs` which is per-SESSION. Null durations are
 * ignored — a page nobody dwelled on shouldn't drag the average to zero. Uses
 * Prisma aggregate so Postgres does the sum/count.
 */
export async function avgTimePerPageByKind(days = 30): Promise<TimePerPageByKind> {
  const since = new Date(Date.now() - days * DAY);
  const base = { createdAt: { gte: since }, durationMs: { not: null }, ...(await ipEx()) };
  const [mk, pt] = await Promise.all([
    db.visit.aggregate({ where: { ...base, kind: "marketing" }, _avg: { durationMs: true }, _count: { durationMs: true } }),
    db.visit.aggregate({ where: { ...base, kind: "portal" }, _avg: { durationMs: true }, _count: { durationMs: true } }),
  ]);
  const marketing: PerKindTime = { avgMs: Math.round(mk._avg.durationMs ?? 0), samples: mk._count.durationMs };
  const portal: PerKindTime = { avgMs: Math.round(pt._avg.durationMs ?? 0), samples: pt._count.durationMs };
  const totalSamples = marketing.samples + portal.samples;
  const overallMs =
    totalSamples > 0
      ? Math.round((marketing.avgMs * marketing.samples + portal.avgMs * portal.samples) / totalSamples)
      : 0;
  return { marketing, portal, overall: { avgMs: overallMs, samples: totalSamples } };
}

