import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { checkRateLimit } from "@/lib/rate-limit";
import { trustedClientIp } from "@/app/api/_lib/client-ip";
import { currentUser } from "@/lib/auth";

export const runtime = "nodejs";

/**
 * Deploy-funnel event sink. Called fire-and-forget by the customer deploy wizards
 * (components/customer/*DeployWizard.tsx) as a person moves through the steps, and
 * by the same wizards when a step throws / a provision call fails. Server-side
 * provisioning failures are recorded via `recordDeployFunnelError` (lib/deploy-funnel.ts)
 * rather than this HTTP path.
 *
 * Records one `DeployFunnelEvent`. Like /api/track it MUST NOT throw or block —
 * analytics is strictly best-effort. It attributes the signed-in account via
 * `currentUser()` (the auth cookie rides the POST) and the stable visitor cookie,
 * so an admin can later tie a stuck/errored session back to a real customer.
 */

const VID_COOKIE = "nx_vid";
const PRODUCTS = new Set(["vps", "game", "hosting"]);
const TYPES = new Set(["step", "error", "complete"]);

function readCookie(req: Request, name: string): string | null {
  const raw = req.headers.get("cookie");
  if (!raw) return null;
  for (const part of raw.split("; ")) {
    if (part.startsWith(`${name}=`)) return part.slice(name.length + 1);
  }
  return null;
}

function cleanId(v: unknown): string | null {
  if (typeof v !== "string") return null;
  const s = v.trim();
  if (!s || s.length > 64 || !/^[A-Za-z0-9._-]+$/.test(s)) return null;
  return s;
}

function cleanStr(v: unknown, max: number): string | null {
  if (typeof v !== "string") return null;
  const s = v.trim().slice(0, max);
  return s || null;
}

export async function POST(req: Request) {
  try {
    const ip = trustedClientIp(req);
    const rl = checkRateLimit(`deploystep:${ip}`, { max: 120, windowMs: 60_000 });
    if (!rl.ok) return new NextResponse(null, { status: 204 });

    const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;

    const product = typeof body.product === "string" ? body.product : "";
    if (!PRODUCTS.has(product)) return NextResponse.json({ ok: true });
    const step = cleanStr(body.step, 60);
    if (!step) return NextResponse.json({ ok: true });
    const stepIndexRaw = typeof body.stepIndex === "number" ? body.stepIndex : Number(body.stepIndex);
    const stepIndex = Number.isFinite(stepIndexRaw) ? Math.max(0, Math.min(50, Math.round(stepIndexRaw))) : 0;
    const type = typeof body.type === "string" && TYPES.has(body.type) ? body.type : "step";

    let userId: string | null = null;
    try {
      userId = (await currentUser())?.id ?? null;
    } catch {
      /* best-effort */
    }
    const vid = readCookie(req, VID_COOKIE);
    const visitorId = vid && /^[A-Za-z0-9-]{8,64}$/.test(vid) ? vid : null;

    await db.deployFunnelEvent.create({
      data: {
        userId,
        visitorId,
        sessionId: cleanId(body.sessionId),
        product,
        step,
        stepIndex,
        type,
        errorCode: type === "error" ? cleanStr(body.errorCode, 60) : null,
        errorMessage: type === "error" ? cleanStr(body.errorMessage, 300) : null,
      },
    });
  } catch {
    /* never surface capture failures */
  }
  return NextResponse.json({ ok: true });
}

// Client-side deploy-funnel beacons. Dependency-free (no server imports) so it is
// safe to pull into the customer wizard client components. Fires fire-and-forget
// POSTs to /api/track/deploy-step; never throws, never blocks the wizard.

export type DeployProduct = "vps" | "game" | "hosting";

/** Read the per-tab session id the VisitTracker maintains, so a funnel event can
 *  be tied to the same session as the pageviews. */
function sessionId(): string | null {
  try {
    return window.sessionStorage.getItem("nx_sid");
  } catch {
    return null;
  }
}

function send(payload: Record<string, unknown>): void {
  try {
    const body = JSON.stringify({ ...payload, sessionId: sessionId() });
    if (typeof navigator !== "undefined" && navigator.sendBeacon) {
      navigator.sendBeacon("/api/track/deploy-step", new Blob([body], { type: "application/json" }));
    } else {
      fetch("/api/track/deploy-step", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body,
        keepalive: true,
      }).catch(() => {});
    }
  } catch {
    /* best-effort */
  }
}

/**
 * Record that the user REACHED a wizard step. De-duped per tab-session so a
 * component re-render / strict-mode double-mount doesn't count a step twice — the
 * funnel measures distinct sessions reaching each step.
 */
export function trackDeployStep(product: DeployProduct, step: string, stepIndex: number): void {
  if (typeof window === "undefined") return;
  const key = `nx_dfstep:${product}:${stepIndex}:${step}`;
  try {
    if (window.sessionStorage.getItem(key)) return;
    window.sessionStorage.setItem(key, "1");
  } catch {
    /* storage disabled — still emit, just without cross-render dedupe */
  }
  send({ product, step, stepIndex, type: "step" });
}

/**
 * Record that a wizard step FAILED (a validation error, or an API/provision call
 * that returned/raised an error). NOT de-duped — every real failure is a signal.
 */
export function trackDeployError(
  product: DeployProduct,
  step: string,
  stepIndex: number,
  errorCode: string,
  errorMessage?: string,
): void {
  if (typeof window === "undefined") return;
  send({ product, step, stepIndex, type: "error", errorCode, errorMessage: errorMessage ?? null });
}

/** Record that the deploy SUCCEEDED (bottom of the funnel). De-duped per session. */
export function trackDeployComplete(product: DeployProduct, step: string, stepIndex: number): void {
  if (typeof window === "undefined") return;
  const key = `nx_dfdone:${product}`;
  try {
    if (window.sessionStorage.getItem(key)) return;
    window.sessionStorage.setItem(key, "1");
  } catch {
    /* ignore */
  }
  send({ product, step, stepIndex, type: "complete" });
}

