import Link from "next/link";
import { requireArea } from "@/lib/rbac";
import { PageHeader, StatCard, Badge } from "@/components/ui/primitives";
import { MeterBar } from "@/components/ui/charts";
import { deployFunnels, type ProductFunnel } from "@/lib/deploy-funnel";

export const dynamic = "force-dynamic";

const WINDOWS = [7, 30, 90] as const;
type Win = (typeof WINDOWS)[number];

const PRODUCT_LABEL: Record<string, string> = { vps: "VPS", game: "Game servers", hosting: "Web hosting" };

function fmtDuration(): string {
  return "";
}

function pct(n: number, d: number): string {
  if (d <= 0) return "0%";
  return `${((n / d) * 100).toFixed(n / d >= 0.1 ? 0 : 1)}%`;
}

function ProductFunnelCard({ f }: { f: ProductFunnel }) {
  const max = Math.max(...f.steps.map((s) => s.reached), 1);
  return (
    <div className="card">
      <div className="flex flex-wrap items-baseline justify-between gap-2">
        <h2 className="font-semibold">{PRODUCT_LABEL[f.product] ?? f.product}</h2>
        <div className="flex flex-wrap gap-3 text-xs text-slate-400">
          <span>
            Started <span className="font-semibold text-slate-200">{f.started.toLocaleString()}</span>
          </span>
          <span>
            Completed <span className="font-semibold text-emerald-300">{f.completed.toLocaleString()}</span>
            <span className="ml-1 text-slate-500">{pct(f.completed, f.started)}</span>
          </span>
          <span>
            Errored <span className="font-semibold text-red-300">{f.erroredSessions.toLocaleString()}</span>
          </span>
        </div>
      </div>
      <p className="mt-1 text-xs text-slate-500">
        How far each session gets through the wizard. Per step: reached · completed-through · abandoned (drop-off) ·
        errored (a bug/provision failure, not just leaving).
      </p>

      <div className="mt-4 space-y-4">
        {f.steps.map((s, i) => (
          <div key={s.step}>
            <div className="mb-1 flex items-baseline justify-between gap-3 text-sm">
              <span className="font-medium">
                {i + 1}. {s.step}
              </span>
              <span className="flex flex-wrap items-baseline gap-x-3 gap-y-0.5 justify-end tabular-nums text-xs">
                <span className="text-slate-200">
                  <span className="font-semibold">{s.reached.toLocaleString()}</span> reached
                </span>
                <span className="text-emerald-300">{s.completedThrough.toLocaleString()} completed-through</span>
                <span className="text-amber-300">
                  {s.abandoned.toLocaleString()} abandoned · {pct(s.abandoned, s.reached)}
                </span>
                {s.erroredSessions > 0 ? (
                  <span className="text-red-300">
                    {s.erroredSessions.toLocaleString()} errored
                    {s.errorEvents > s.erroredSessions ? ` (${s.errorEvents} events)` : ""}
                  </span>
                ) : (
                  <span className="text-slate-600">0 errored</span>
                )}
              </span>
            </div>
            <MeterBar value={s.reached} max={max} color={s.erroredSessions > 0 ? "#f87171" : "#8a70fb"} />
            {s.topErrors.length > 0 && (
              <ul className="mt-1.5 space-y-1 pl-1">
                {s.topErrors.map((e, j) => (
                  <li key={j} className="flex items-baseline gap-2 text-xs">
                    <Badge tone="red">{e.code ?? "error"}</Badge>
                    <span className="min-w-0 truncate text-slate-400" title={e.message ?? ""}>
                      {e.message ?? "—"}
                    </span>
                    <span className="shrink-0 tabular-nums text-slate-500">×{e.count}</span>
                  </li>
                ))}
              </ul>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}

export default async function DeployFunnelPage({
  searchParams,
}: {
  searchParams: Promise<{ days?: string }>;
}) {
  await requireArea("analytics");
  void fmtDuration;

  const sp = await searchParams;
  const days: Win = WINDOWS.includes(Number(sp.days) as Win) ? (Number(sp.days) as Win) : 30;

  const funnels = await deployFunnels(days);

  const totalStarted = funnels.reduce((s, f) => s + f.started, 0);
  const totalCompleted = funnels.reduce((s, f) => s + f.completed, 0);
  const totalErrored = funnels.reduce((s, f) => s + f.erroredSessions, 0);

  return (
    <div className="space-y-6">
      <PageHeader
        title="Deploy funnel"
        sub="How far customers get through each deploy wizard, and where a drop-off is a BUG (errored) versus an abandonment."
      />

      <div className="flex gap-2">
        {WINDOWS.map((w) => (
          <Link
            key={w}
            href={`/admin/deploy-funnel?days=${w}`}
            className={`rounded-lg border px-3 py-1.5 text-sm ${
              w === days
                ? "border-brand-400/60 bg-brand-500/15 text-brand-200"
                : "border-white/[0.08] text-slate-400 hover:text-slate-200"
            }`}
          >
            {w}d
          </Link>
        ))}
      </div>

      <div className="grid grid-cols-3 gap-4">
        <StatCard label="Deploys started" value={totalStarted.toLocaleString()} delta={`all products · ${days}d`} />
        <StatCard
          label="Deploys completed"
          value={totalCompleted.toLocaleString()}
          delta={totalStarted > 0 ? `${pct(totalCompleted, totalStarted)} of started` : "no starts yet"}
          deltaGood={totalCompleted > 0}
        />
        <StatCard
          label="Sessions with errors"
          value={totalErrored.toLocaleString()}
          delta="a failed step, not abandonment"
          deltaGood={totalErrored === 0}
        />
      </div>

      {funnels.length === 0 ? (
        <div className="card">
          <p className="py-8 text-center text-sm text-slate-500">
            No deploy-wizard activity in this window yet. Events appear here once customers open a deploy wizard
            (requires the DeployFunnelEvent table — apply prisma/manual-migration-deploy-funnel.sql).
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          {funnels.map((f) => (
            <ProductFunnelCard key={f.product} f={f} />
          ))}
        </div>
      )}
    </div>
  );
}

