const DAY = 86_400_000;
const EVENT_CAP = 100_000;

export type DeployProduct = "vps" | "game" | "hosting";

/**
 * Typed accessor for the DeployFunnelEvent delegate.
 *
 * The generated Prisma client in this worktree does not yet carry this model
 * (its node_modules is symlinked to prod, which we must not regenerate here — the
 * owner regenerates the client when they apply prisma/manual-migration-deploy-funnel.sql
 * at deploy). This shim types every read/write against the model's real shape so
 * call sites stay type-safe and `tsc` is clean now, and binds to the genuine
 * delegate the moment the client is regenerated. It is the ONLY place that reaches
 * for the delegate, so there is a single seam to delete once the model is generated.
 */
export type DeployFunnelEventRow = {
  id: string;
  userId: string | null;
  visitorId: string | null;
  sessionId: string | null;
  product: string;
  step: string;
  stepIndex: number;
  type: string;
  errorCode: string | null;
  errorMessage: string | null;
  createdAt: Date;
};

type DeployFunnelDelegate = {
  create(args: { data: Partial<DeployFunnelEventRow> }): Promise<DeployFunnelEventRow>;
  findMany(args: {
    where?: Record<string, unknown>;
    select?: Record<string, boolean>;
    take?: number;
    orderBy?: Record<string, "asc" | "desc">;
  }): Promise<DeployFunnelEventRow[]>;
};

function dfe(): DeployFunnelDelegate {
  return (db as unknown as { deployFunnelEvent: DeployFunnelDelegate }).deployFunnelEvent;
}

